package org.updraft.betterstatus.velocity;
import com.google.inject.Inject;import com.velocitypowered.api.command.*;import com.velocitypowered.api.event.Subscribe;import com.velocitypowered.api.event.connection.PluginMessageEvent;import com.velocitypowered.api.event.proxy.*;import com.velocitypowered.api.plugin.Plugin;import com.velocitypowered.api.plugin.annotation.DataDirectory;import com.velocitypowered.api.proxy.*;import com.velocitypowered.api.proxy.messages.MinecraftChannelIdentifier;import net.kyori.adventure.text.Component;import org.slf4j.Logger;import org.updraft.betterstatus.model.*;import org.updraft.betterstatus.monitor.*;import org.updraft.betterstatus.protocol.StatusProtocol;import org.updraft.betterstatus.storage.HistoryStore;import org.updraft.betterstatus.notify.DiscordNotifier;import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
@Plugin(id="betterstatus",name="BetterStatus",version="2.0.0",authors={"MrFrenchGuy23"}) public final class VelocityStatusPlugin {
 private static final MinecraftChannelIdentifier CHANNEL=MinecraftChannelIdentifier.create("bungeecord","main");private final ProxyServer proxy;private final Logger logger;private final Path data;private MonitorEngine monitor;private HistoryStore history;private ExecutorService alerts;private DiscordNotifier discord;
 @Inject public VelocityStatusPlugin(ProxyServer proxy,Logger logger,@DataDirectory Path data){this.proxy=proxy;this.logger=logger;this.data=data;}
 @Subscribe public void onInit(ProxyInitializeEvent e){try{Files.createDirectories(data);Path f=data.resolve("config.properties");Properties p=new Properties();if(Files.exists(f))try(Reader r=Files.newBufferedReader(f)){p.load(r);}else{p.setProperty("servers","lobby,survival,dev");p.setProperty("update-interval-seconds","5");p.setProperty("timeout-millis","3000");p.setProperty("failure-threshold","3");p.setProperty("recovery-threshold","2");p.setProperty("warning-ping-millis","150");p.setProperty("critical-ping-millis","300");p.setProperty("discord-webhook-url","");try(Writer w=Files.newBufferedWriter(f)){p.store(w,"BetterStatus Velocity configuration");}}Map<String,PingProvider> providers=new LinkedHashMap<>();for(String raw:p.getProperty("servers","").split(",")){String n=raw.trim();if(n.isEmpty())continue;proxy.getServer(n).ifPresentOrElse(s->providers.put(n,()->ping(s)),()->logger.warn("Configured server not found: {}",n));}MonitorConfig c=new MonitorConfig(number(p,"update-interval-seconds",5)*1000,number(p,"timeout-millis",3000),(int)number(p,"failure-threshold",3),(int)number(p,"recovery-threshold",2),number(p,"warning-ping-millis",150),number(p,"critical-ping-millis",300));monitor=new MonitorEngine(providers,c);alerts=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"BetterStatus-Alerts");t.setDaemon(true);return t;});discord=new DiscordNotifier(p.getProperty("discord-webhook-url",""),alerts);try{history=new HistoryStore("jdbc:sqlite:"+data.resolve("history.db").toAbsolutePath());}catch(Exception ex){logger.warn("History disabled: {}",ex.getMessage());}monitor.addListener((a,b)->{if(history!=null)try{history.record(b);}catch(Exception ignored){}discord.sendTransition(a,b);});proxy.getChannelRegistrar().register(CHANNEL);proxy.getEventManager().register(this,this);CommandMeta meta=proxy.getCommandManager().metaBuilder("srvstatus").aliases("ss").plugin(this).build();proxy.getCommandManager().register(meta,new StatusCommand());monitor.start();logger.info("BetterStatus enabled on Velocity; monitoring {} backend(s).",providers.size());}catch(Exception ex){logger.error("Could not initialize BetterStatus",ex);}}
 public org.updraft.betterstatus.api.ServerStatusApi api(){return monitor;}
 private long number(Properties p,String k,long d){try{return Long.parseLong(p.getProperty(k,Long.toString(d)));}catch(NumberFormatException e){return d;}}
 private CompletableFuture<PingResult> ping(RegisteredServer server){long start=System.nanoTime();return server.ping().orTimeout(3,TimeUnit.SECONDS).thenApply(p->{int online=p.getPlayers().map(x->x.getOnline()).orElse(0),max=p.getPlayers().map(x->x.getMax()).orElse(0);return new PingResult(true,online,max,TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start),p.getDescriptionComponent().toString(),p.getVersion().getName(),"");}).exceptionally(x->PingResult.failure(x.getClass().getSimpleName()));}
 @Subscribe public void onPluginMessage(PluginMessageEvent e){if(!CHANNEL.equals(e.getIdentifier())||!(e.getSource() instanceof ServerConnection source))return;try{DataInputStream in=new DataInputStream(new ByteArrayInputStream(e.getData()));if(!StatusProtocol.SUBCHANNEL.equals(in.readUTF()))return;source.sendPluginMessage(CHANNEL,StatusProtocol.encode(monitor.getServers(),"§aOnline","§cOffline","§6Maintenance"));e.setResult(PluginMessageEvent.ForwardResult.handled());}catch(Exception ex){logger.warn("Rejected malformed status request");}}
 @Subscribe public void onShutdown(ProxyShutdownEvent e){if(monitor!=null)monitor.close();if(history!=null)try{history.close();}catch(Exception ignored){}if(alerts!=null)alerts.shutdownNow();proxy.getChannelRegistrar().unregister(CHANNEL);}
 private final class StatusCommand implements SimpleCommand{public void execute(Invocation i){if(!i.source().hasPermission("serverstatus.admin")){i.source().sendMessage(Component.text("No permission."));return;}String[] a=i.arguments();if(a.length==0||a[0].equalsIgnoreCase("list")){for(ServerSnapshot s:monitor.getServers())i.source().sendMessage(Component.text(s.name()+": "+s.state()+" ("+s.players()+"/"+s.maxPlayers()+", "+s.pingMillis()+"ms)"));}else if(a[0].equalsIgnoreCase("check")){if(a.length<2||a[1].equalsIgnoreCase("all"))monitor.refreshAll();else monitor.checkServer(a[1]);i.source().sendMessage(Component.text("Status check queued."));}else if(a[0].equalsIgnoreCase("info")&&a.length>1)monitor.getServer(a[1]).ifPresentOrElse(s->i.source().sendMessage(Component.text(s.toString())),()->i.source().sendMessage(Component.text("Unknown server.")));else i.source().sendMessage(Component.text("/srvstatus [list|info <server>|check <server|all>]"));}public List<String> suggest(Invocation i){return List.of("list","info","check");}public boolean hasPermission(Invocation i){return i.source().hasPermission("serverstatus.view");}}
}